window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-933e09777801bb0f"]={"versions": [{"id": "FIG-933e09777801bb0f", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Adaptive Platform Timing Extensions zur Modellierung komplexer Timing-Ereignisse (<em>Complex timing event</em>). Es definiert die Metamodell-Struktur zur formalen Beschreibung von Ereignisvorkommen basierend auf logischen und mathematischen Ausdrücken innerhalb der Timing-Beschreibung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>TimingDescription::TimingDescriptionEvent</code>: Abstrakte Basisklasse (kursiv dargestellt) im Namensraum <code>TimingDescription</code>, generalisiert durch <code>TDEventComplex</code>. Sie besitzt eine Kompositionsbeziehung <code>+occurrenceExpression</code> mit Multiplizität <code>0..1</code> zur Klasse <code>TDEventOccurrenceExpression::TDEventOccurrenceExpression</code>.\n</li><li><code>TDEventComplex</code>: Konkrete Spezialisierung von <code>TimingDescriptionEvent</code> über eine Generalisierungsbeziehung.\n</li><li><code>TDEventOccurrenceExpression::TDEventOccurrenceExpression</code>: Repräsentiert den Ausdruck für das Auftreten von Ereignissen und aggregiert über eine Komposition <code>+formula</code> mit Multiplizität <code>1</code> die Klasse <code>«atpMixedString» TDEventOccurrenceExpression::TDEventOccurrenceExpressionFormula</code>.\n</li><li><code>«atpMixedString» TDEventOccurrenceExpression::TDEventOccurrenceExpressionFormula</code>: Spezialisierte Formel-Klasse (Stereotyp <code>«atpMixedString»</code>, Subtyp oder Konzept von <code>FormulaExpression</code>), die über eine gerichtete Assoziation <code>+event</code> mit Multiplizität <code>0..1</code> und Eigenschaft <code>{subsets atpReference}</code> zurück auf <code>TimingDescriptionEvent</code> referenziert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Die funktionale Semantik besteht darin, dass ein komplexes Timing-Ereignis (<code>TDEventComplex</code>) über seinen zugeordneten <code>occurrenceExpression</code> und die darin eingebettete Formel (<code>formula</code>) das Eintreten von Ereignissen auf Basis referenzierter Basisereignisse (<code>event</code>) auswertet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für die Spezifikation und Auswertung von Timing-Ereignissen in AUTOSAR Adaptive. Entwickler müssen beachten, dass <code>TDEventOccurrenceExpressionFormula</code> als <code>«atpMixedString»</code> formuliert wird und über <code>{subsets atpReference}</code> Referenzen auf andere <code>TimingDescriptionEvent</code>-Instanzen einbindet, um kombinierte bzw. abgeleitete Timing-Bedingungen zu formulieren.</p>"}, {"id": "FIG-20fe74b57b63a535", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Adaptive Platform Timing Extensions zur Modellierung komplexer Timing-Ereignisse (<em>Complex timing event</em>). Es definiert die Metamodell-Struktur zur formalen Beschreibung von Ereignisvorkommen basierend auf logischen und mathematischen Ausdrücken innerhalb der Timing-Beschreibung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>TimingDescriptionEvent</code>: Abstrakte Basisklasse (kursiv dargestellt, zugehörig zu <code>TimingDescription</code>), generalisiert durch <code>TDEventComplex</code>. Sie besitzt eine Kompositionsbeziehung <code>+occurrenceExpression</code> mit Multiplizität <code>0..1</code> zur Klasse <code>TDEventOccurrenceExpression</code>.\n</li><li><code>TDEventComplex</code>: Konkrete Spezialisierung von <code>TimingDescriptionEvent</code> über eine Generalisierungsbeziehung.\n</li><li><code>TDEventOccurrenceExpression</code>: Repräsentiert den Ausdruck für das Auftreten von Ereignissen und aggregiert über eine Komposition <code>+formula</code> mit Multiplizität <code>1</code> die Klasse <code>«atpMixedString» TDEventOccurrenceExpressionFormula</code>.\n</li><li><code>«atpMixedString» TDEventOccurrenceExpressionFormula</code>: Spezialisierte Formel-Klasse (Stereotyp <code>«atpMixedString»</code>, Subtyp oder Konzept von <code>FormulaExpression</code>), die über eine gerichtete Assoziation <code>+event</code> mit Multiplizität <code>0..1</code> und Eigenschaft <code>{subsets atpReference}</code> zurück auf <code>TimingDescriptionEvent</code> referenziert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Die funktionale Semantik besteht darin, dass ein komplexes Timing-Ereignis (<code>TDEventComplex</code>) über seinen zugeordneten <code>occurrenceExpression</code> und die darin eingebettete Formel (<code>formula</code>) das Eintreten von Ereignissen auf Basis referenzierter Basisereignisse (<code>event</code>) auswertet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für die Spezifikation und Auswertung von Timing-Ereignissen in AUTOSAR Adaptive. Entwickler müssen beachten, dass <code>TDEventOccurrenceExpressionFormula</code> als <code>«atpMixedString»</code> formuliert wird und über <code>{subsets atpReference}</code> Referenzen auf andere <code>TimingDescriptionEvent</code>-Instanzen einbindet, um kombinierte bzw. abgeleitete Timing-Bedingungen zu formulieren.</p>"}], "trans": [{"from": "FIG-933e09777801bb0f", "to": "FIG-20fe74b57b63a535", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Die Paket-Präfixe (<code>TimingDescription::</code>, <code>TDEventOccurrenceExpression::</code>) in den Klassennamen der Entitäten <code>TimingDescriptionEvent</code>, <code>TDEventOccurrenceExpression</code> und <code>TDEventOccurrenceExpressionFormula</code> wurden entfernt.\n</li></ul>"}]};
